    const resolvedRelicId = relicId === 'relic_gamble'
      ? RELIC_DEFS.filter(r => r.id !== 'relic_gamble')[Math.floor(Math.random() * (RELIC_DEFS.length - 1))].id
      : relicId;
    setActiveRelicId(resolvedRelicId);
