            if (isCR('cm_druid_2') && ally.type === 'druid') { const d2bonus = Math.min((ally as any)._cm_druid2_bonus ?? 0, 2.0); dmg = Math.round(dmg * (1 + d2bonus)); } // capped at +200% (40 cycles)
            // cm_druid_5: double all druid damage
