            if (isCR('cm_warlock_2')) { const kills = Math.min((currentPlayer as any)._cm_warlock2_kills ?? 0, 20); dmg = Math.round(dmg * (1 + kills * 0.05)); } // capped at 20 kills = +100%
            // Scroll of Fury (+40%) and War Banner (+25%) — temporary wave buffs
            if ((currentPlayer as any).furyScrollActive) dmg = Math.round(dmg * 1.40);
