              // Codex of Sins: +10% vs most frequent act enemy type
              if ((ally as any)._codexBonus) dmg = Math.round(dmg * 1.10);
              // Sentence: +30% damage while target is sentenced
              const sentencedId = (currentPlayer as any)._sentenceTarget;
