            if (archerCuts < 5) options.push({ id: `archer-thousandcuts-${uid()}`, title: t('ui.cardx.archer-thousandcuts.title') + (archerCuts > 0 ? ` (${archerCuts}/5)` : ''), description: t('ui.cardx.archer-thousandcuts.description', { cur: archerCuts * 6, next: (archerCuts + 1) * 6 }), rarity: 'legendary', iconType: 'special', iconSpecial: <Swords size={64} className="text-yellow-400" />, apply: (p) => ({ ...p, allies: p.allies.map(a => a.type === 'archer' ? { ...a, perks: { ...a.perks, archerThousandCuts: a.perks?.archerThousandCuts ? a.perks?.archerThousandCuts + 1 : 1 }, damage: Math.round(a.damage * 1.06) } : a) }) });
