                            <PixelPanel material="gold" style={{ padding: '4px 10px' }}>
                              <span className="pixel-text" style={{ ...TYPE.label, fontSize: 13, color: MATERIAL.gold.base }}>{t('ui.demo.wishlist.fullGame')}</span>
                            </PixelPanel>
